# Simpler approach: copy everything from the bounding box, to the shifted position
# But don't copy the specific cell that was at offset (5,3) in the pattern

def transform(grid):
    H, W = len(grid), len(grid[0])
    new_grid = [row[:] for row in grid]

    # Find bounding box
    min_r, max_r = H, 0
    min_c, max_c = W, 0

    for r in range(H):
        for c in range(W):
            if grid[r][c] != 0:
                min_r = min(min_r, r)
                max_r = max(max_r, r)
                min_c = min(min_c, c)
                max_c = max(max_c, c)

    if min_r < H and min_c < W:
        start_r, start_c = min_r + 5, min_c + 3

        for dr in range(max_r - min_r + 1):
            for dc in range(max_c - min_c + 1):
                val = grid[min_r + dr][min_c + dc]
                if val != 0:
                    # Don't copy if val is 5 at the specific "5" offset position
                    # OR: don't copy the 5 that's offset by (5,3) from patternmin
                    nr, nc = start_r + dr, start_c + dc
                    if nr < H and nc < W:
                        # Skip copying the cell that maps to input's +5,+3 from min
                        if not (dr == 5 and dc == 3):  # Skip copy of (2,3) which is min+(2,3) from min+(5,3)
                           if val != 0:
                               new_grid[nr][nc] = val

    return new_grid

